pub fn written(site: Site, old: &Old, new: &mut Build, at: Node, cx: &mut Context) -> Result<(), Halt> {
    match site.patch() {
        12 => match site.index() {
            0 => p0012::assignment_down(old, new, at, cx),
            _ => Err(Halt::NoSite(site)),
        },
        _ => Err(Halt::NoSite(site)),
    }
}

pub fn sites(site: Site, old: &Old, new: &mut Build, at: Node) -> Result<(), Halt> {
    written(site, old, new, at, &mut Context::default())
}

